   [192]={next_id=193, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="陛下和“双冕王厅”确实赋予了贵族特殊的权力，但是作为代价，贵族的表现即是克洛瓦德的颜面。", msg_color="", msg_size=0, talker="军装少女", audio="", img="arts/ui/bg/story/storybg_10_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4525", 0, 0, 116.5, 191.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
